function highlight(strings, fname1, fname2) {
 let x = fname1.toUpperCase();
 let y = fname2.toUpperCase();
 return strings[0] + x + strings[1] + y + strings[2];
}

let name1 = "John";
let name2 = "Jane";

let text = highlight`Hello ${name1} and ${name2}, how are you?`;

