const Header = lazy(() => import('./Header'));
const Content = lazy(() => import('./Content'));
const Sidebar = lazy(() => import('./Sidebar'));

function App() {
 return (
 <div>
 <Suspense fallback={<div>Loading...</div>}>
 <Header />
 <div style={{ display: 'flex' }}>
 <Sidebar />
 <Content />
 </div>
 </Suspense>
 </div>
 );
}

createRoot(document.getElementById('root')).render(
 <App />
);

